  "seats": 5,
  "body_style": "Crossover",
  "cargo_l_seats_up": {
    "value": 723,
    "confidence": "Medium",
    "source": {
      "url": "https://www.hyundaicanada.com/en/showroom/kona-electric/specs",
      "name": "Hyundai Canada Kona Electric specs",
      "accessed": "2026-04-24"
    },
    "notes": "SAE behind-rear-seat measurement varies; 332 L is below-tonneau (EU/floor only). 723 L is to roof, behind 2nd row, per Hyundai NA brochure."
  },
  "cargo_l_seats_down": {
    "value": 1814,
    "confidence": "Medium",
    "source": {
